pseudocode:
dist[s] = 0; dist[v ≠ s] = ∞
priority queue Q ← all nodes by dist
while Q not empty:
    u ← extract_min(Q)
    for each (u,v,w) with v unsettled:
        if dist[u] + w < dist[v]:
            dist[v] ← dist[u] + w
            parent[v] ← u; decrease_key(Q,v)

forest ← ∅; make_set(v) for each vertex v
for (u,v,w) in edges sorted by increasing weight:
    if find(u) ≠ find(v):
        union(u,v)
        forest ← forest ∪ {(u,v,w)}
return forest
